extern int32_t जावापरतजाळे_संचारद्वार(int32_t,int32_t,int32_t), जावापरतजाळे_बाइंड_करा(int32_t,int32_t,int32_t);
extern int32_t जावापरतजाळे_पाठवा(int32_t,int32_t,int32_t,int32_t), जावापरतजाळे_स्वीकार(int32_t,int32_t);
extern int32_t जावापरतजाळे_पॉर्ट(int32_t), जावापरतजाळे_पत्ता(int32_t), जावापरतजाळे_समकक्ष(int32_t), जावापरतजाळे_मिटवा(int32_t);
extern int32_t जावाजाळे_ठेवा(int32_t,int32_t),जावाजाळे_मिळवा(int32_t);
extern int32_t जावापरतप्रवाह_तयार_करा(void),जावापरतप्रवाह_बाइंड_करा(int32_t,int32_t,int32_t),जावापरतप्रवाह_ऐका(int32_t,int32_t);
extern int32_t जावापरतप्रवाह_कनेक्ट(int32_t,int32_t,int32_t),जावापरतप्रवाह_स्वीकारा(int32_t),जावापरतप्रवाह_वाचा(int32_t,int32_t),जावापरतप्रवाह_लिहा(int32_t,int32_t);
