static int बाह्य[24];
static int कोणतेही_पत्ता[24], दुहेरी_घटनाग्राहक[24], स्वतंत्रसंदेशसंचार_बाह्य_समकक्ष[8], बांधलेले_पत्ता[8];
static int बाह्य_संख्या(int संचिका_हाताळा) { return संचिका_हाताळा>=32 && संचिका_हाताळा<56 ? बाह्य[संचिका_हाताळा-32]-1 : -1; }
static int चिकटवा_मजकूर(int संचिका_हाताळा,int टाइप_करा_वर्गवारी) {
    if(संचिका_हाताळा<32||संचिका_हाताळा>=56)return -9;int मागील_आयटम=बाह्य_संख्या(संचिका_हाताळा);if(मागील_आयटम>=0)return मागील_आयटम;
    int आयटम_संख्या=संचारद्वार_संचारटोक_तयार_करा(टाइप_करा_वर्गवारी);if(आयटम_संख्या>=0)बाह्य[संचिका_हाताळा-32]=आयटम_संख्या+1;return आयटम_संख्या;
}
int32_t जावाजाळे_संचारद्वार(int32_t पहिले_मूल्य,int32_t दुसरे_मूल्य,int32_t वर्ण_कोड){return जावापरतजाळे_संचारद्वार(पहिले_मूल्य,दुसरे_मूल्य,वर्ण_कोड);}
int32_t जावाजाळे_बाइंड_करा(int32_t संचिका_हाताळा,int32_t इंटरनेट_पत्ता,int32_t पोर्ट_नंबर){
    if(इंटरनेट_पत्ता==0x7f000001)return जावापरतजाळे_बाइंड_करा(संचिका_हाताळा,इंटरनेट_पत्ता,पोर्ट_नंबर);
    if(इंटरनेट_पत्ता!=0&&इंटरनेट_पत्ता!=संचारजाळे_राज्य_वाचा(0,0))return -99;
    int परतलेले_मूल्य=जावापरतजाळे_बाइंड_करा(संचिका_हाताळा,0,पोर्ट_नंबर);if(परतलेले_मूल्य<0)return परतलेले_मूल्य;
    int आयटम_संख्या=चिकटवा_मजकूर(संचिका_हाताळा,2);if(आयटम_संख्या<0)return आयटम_संख्या;परतलेले_मूल्य=जाळे_बाइंड_करा(आयटम_संख्या,संचारजाळे_राज्य_वाचा(0,0),जावापरतजाळे_पॉर्ट(संचिका_हाताळा));if(!परतलेले_मूल्य)बांधलेले_पत्ता[संचिका_हाताळा-32]=इंटरनेट_पत्ता;return परतलेले_मूल्य;
}
int32_t जावाजाळे_पाठवा(int32_t संचिका_हाताळा,int32_t इंटरनेट_पत्ता,int32_t पोर्ट_नंबर,int32_t आकार){
    if(इंटरनेट_पत्ता==0x7f000001)return जावापरतजाळे_पाठवा(संचिका_हाताळा,इंटरनेट_पत्ता,पोर्ट_नंबर,आकार);
    if(आकार<0||आकार>512)return -90;if(पोर्ट_नंबर<1||पोर्ट_नंबर>65535)return -22;
    if(जावापरतजाळे_पॉर्ट(संचिका_हाताळा)<0)return -9;
    if(जावापरतजाळे_पत्ता(संचिका_हाताळा)==0x7f000001)return -101;
    int आयटम_संख्या=बाह्य_संख्या(संचिका_हाताळा);if(आयटम_संख्या<0){int परतलेले_मूल्य=0;if(जावापरतजाळे_पॉर्ट(संचिका_हाताळा)==0)परतलेले_मूल्य=जावापरतजाळे_बाइंड_करा(संचिका_हाताळा,0,0);if(परतलेले_मूल्य<0)return परतलेले_मूल्य;आयटम_संख्या=चिकटवा_मजकूर(संचिका_हाताळा,2);if(आयटम_संख्या<0)return आयटम_संख्या;परतलेले_मूल्य=जाळे_बाइंड_करा(आयटम_संख्या,संचारजाळे_राज्य_वाचा(0,0),जावापरतजाळे_पॉर्ट(संचिका_हाताळा));if(परतलेले_मूल्य<0)return परतलेले_मूल्य;}
    unsigned char डेटा[512];for(int क्रमांक_अनुक्रमणिका=0;क्रमांक_अनुक्रमणिका<आकार;क्रमांक_अनुक्रमणिका++)डेटा[क्रमांक_अनुक्रमणिका]=जावाजाळे_मिळवा(क्रमांक_अनुक्रमणिका);return स्वतंत्रसंदेश_पाठवा(आयटम_संख्या,डेटा,आकार,इंटरनेट_पत्ता,पोर्ट_नंबर);
}
int32_t जावाजाळे_स्वीकार(int32_t संचिका_हाताळा,int32_t आकार){
    int आयटम_संख्या=बाह्य_संख्या(संचिका_हाताळा);if(आयटम_संख्या<0)return जावापरतजाळे_स्वीकार(संचिका_हाताळा,आकार);if(आकार<0||आकार>512)return -22;
    int स्थानिक=जावापरतजाळे_स्वीकार(संचिका_हाताळा,आकार);if(स्थानिक!=-11){स्वतंत्रसंदेशसंचार_बाह्य_समकक्ष[संचिका_हाताळा-32]=0;return स्थानिक;}
    unsigned char डेटा[512];int परतलेले_मूल्य=स्वतंत्रसंदेश_स्वीकारा(आयटम_संख्या,डेटा,आकार);if(परतलेले_मूल्य>=0)स्वतंत्रसंदेशसंचार_बाह्य_समकक्ष[संचिका_हाताळा-32]=1;for(int क्रमांक_अनुक्रमणिका=0;क्रमांक_अनुक्रमणिका<परतलेले_मूल्य;क्रमांक_अनुक्रमणिका++)जावाजाळे_ठेवा(क्रमांक_अनुक्रमणिका,डेटा[क्रमांक_अनुक्रमणिका]);return परतलेले_मूल्य;
}
int32_t जावाजाळे_पॉर्ट(int32_t संचिका_हाताळा){int आयटम_संख्या=बाह्य_संख्या(संचिका_हाताळा);return आयटम_संख्या<0?जावापरतजाळे_पॉर्ट(संचिका_हाताळा):(int32_t)संचारजाळे_पोर्ट_नंबर(आयटम_संख्या);}
int32_t जावाजाळे_पत्ता(int32_t संचिका_हाताळा){return बाह्य_संख्या(संचिका_हाताळा)<0?जावापरतजाळे_पत्ता(संचिका_हाताळा):बांधलेले_पत्ता[संचिका_हाताळा-32];}
int32_t जावाजाळे_समकक्ष(int32_t संचिका_हाताळा){int आयटम_संख्या=बाह्य_संख्या(संचिका_हाताळा);return आयटम_संख्या<0||!स्वतंत्रसंदेशसंचार_बाह्य_समकक्ष[संचिका_हाताळा-32]?जावापरतजाळे_समकक्ष(संचिका_हाताळा):(int32_t)समकक्ष_पोर्ट_नंबर(आयटम_संख्या);}
int32_t जावाजाळे_दूरस्_थ(int32_t संचिका_हाताळा){int आयटम_संख्या=बाह्य_संख्या(संचिका_हाताळा);return आयटम_संख्या<0||!स्वतंत्रसंदेशसंचार_बाह्य_समकक्ष[संचिका_हाताळा-32]?0x7f000001:(int32_t)जाळे_समकक्ष_पत्ता(आयटम_संख्या);}
int32_t जावाजाळे_मिटवा(int32_t संचिका_हाताळा){int आयटम_संख्या=बाह्य_संख्या(संचिका_हाताळा);if(आयटम_संख्या>=0){संचारजाळे_मिटवा(आयटम_संख्या);बाह्य[संचिका_हाताळा-32]=0;}if(संचिका_हाताळा>=32&&संचिका_हाताळा<40)स्वतंत्रसंदेशसंचार_बाह्य_समकक्ष[संचिका_हाताळा-32]=बांधलेले_पत्ता[संचिका_हाताळा-32]=0;return जावापरतजाळे_मिटवा(संचिका_हाताळा);}
int32_t जावाप्रवाह_तयार_करा(void){return जावापरतप्रवाह_तयार_करा();}
int32_t जावाप्रवाह_बाइंड_करा(int32_t संचिका_हाताळा,int32_t इंटरनेट_पत्ता,int32_t पोर्ट_नंबर){
    if(इंटरनेट_पत्ता==0||इंटरनेट_पत्ता==0x7f000001){int परतलेले_मूल्य=जावापरतप्रवाह_बाइंड_करा(संचिका_हाताळा,इंटरनेट_पत्ता,पोर्ट_नंबर);if(!परतलेले_मूल्य)कोणतेही_पत्ता[संचिका_हाताळा-32]=इंटरनेट_पत्ता==0;return परतलेले_मूल्य;}
    if(इंटरनेट_पत्ता!=संचारजाळे_राज्य_वाचा(0,0))return -99;int परतलेले_मूल्य=जावापरतप्रवाह_बाइंड_करा(संचिका_हाताळा,0,पोर्ट_नंबर);if(परतलेले_मूल्य<0)return परतलेले_मूल्य;
    int आयटम_संख्या=चिकटवा_मजकूर(संचिका_हाताळा,1);return आयटम_संख्या<0?आयटम_संख्या:जाळे_बाइंड_करा(आयटम_संख्या,इंटरनेट_पत्ता,जावापरतप्रवाह_पॉर्ट(संचिका_हाताळा));
}
int32_t जावाप्रवाह_ऐका(int32_t संचिका_हाताळा,int32_t प्रलंबितरांग){
    int आयटम_संख्या=बाह्य_संख्या(संचिका_हाताळा);if(आयटम_संख्या<0){int परतलेले_मूल्य=जावापरतप्रवाह_ऐका(संचिका_हाताळा,प्रलंबितरांग);if(परतलेले_मूल्य<0||!कोणतेही_पत्ता[संचिका_हाताळा-32])return परतलेले_मूल्य;
        आयटम_संख्या=चिकटवा_मजकूर(संचिका_हाताळा,1);if(आयटम_संख्या<0)return आयटम_संख्या;परतलेले_मूल्य=जाळे_बाइंड_करा(आयटम_संख्या,संचारजाळे_राज्य_वाचा(0,0),जावापरतप्रवाह_पॉर्ट(संचिका_हाताळा));if(परतलेले_मूल्य<0)return परतलेले_मूल्य;दुहेरी_घटनाग्राहक[संचिका_हाताळा-32]=1;
    }return प्रलंबितरांग<1?-22:जाळे_ऐका(आयटम_संख्या);
}
int32_t जावाप्रवाह_कनेक्ट(int32_t संचिका_हाताळा,int32_t इंटरनेट_पत्ता,int32_t पोर्ट_नंबर){
    if(इंटरनेट_पत्ता==0x7f000001 && बाह्य_संख्या(संचिका_हाताळा)<0)return जावापरतप्रवाह_कनेक्ट(संचिका_हाताळा,इंटरनेट_पत्ता,पोर्ट_नंबर);
    if(जावापरतप्रवाह_पॉर्ट(संचिका_हाताळा)<0)return -9;int आयटम_संख्या=चिकटवा_मजकूर(संचिका_हाताळा,1);return आयटम_संख्या<0?आयटम_संख्या:जाळे_कनेक्ट(आयटम_संख्या,इंटरनेट_पत्ता,पोर्ट_नंबर);
}
int32_t जावाप्रवाह_स्वीकारा(int32_t संचिका_हाताळा){
    int आयटम_संख्या=बाह्य_संख्या(संचिका_हाताळा);if(आयटम_संख्या<0)return जावापरतप्रवाह_स्वीकारा(संचिका_हाताळा);
    if(दुहेरी_घटनाग्राहक[संचिका_हाताळा-32]){int स्थानिक=जावापरतप्रवाह_स्वीकारा(संचिका_हाताळा);if(स्थानिक!=-11)return स्थानिक;}
    int समकक्ष_मूल्य=जाळे_स्वीकारा(आयटम_संख्या);if(समकक्ष_मूल्य<0)return समकक्ष_मूल्य;
    int लक्ष्य=जावापरतप्रवाह_तयार_करा();if(लक्ष्य<0){संचारजाळे_मिटवा(समकक्ष_मूल्य);return लक्ष्य;}बाह्य[लक्ष्य-32]=समकक्ष_मूल्य+1;return लक्ष्य;
}
int32_t जावाप्रवाह_वाचा(int32_t संचिका_हाताळा,int32_t आकार){
    int आयटम_संख्या=बाह्य_संख्या(संचिका_हाताळा);if(आयटम_संख्या<0)return जावापरतप्रवाह_वाचा(संचिका_हाताळा,आकार);if(आकार<0||आकार>512)return -22;
    unsigned char डेटा[512];int परतलेले_मूल्य=जाळे_वाचा(आयटम_संख्या,डेटा,आकार);for(int क्रमांक_अनुक्रमणिका=0;क्रमांक_अनुक्रमणिका<परतलेले_मूल्य;क्रमांक_अनुक्रमणिका++)जावाजाळे_ठेवा(क्रमांक_अनुक्रमणिका,डेटा[क्रमांक_अनुक्रमणिका]);return परतलेले_मूल्य;
}
int32_t जावाप्रवाह_लिहा(int32_t संचिका_हाताळा,int32_t आकार){
    int आयटम_संख्या=बाह्य_संख्या(संचिका_हाताळा);if(आयटम_संख्या<0)return जावापरतप्रवाह_लिहा(संचिका_हाताळा,आकार);if(आकार<0||आकार>512)return -22;
    unsigned char डेटा[512];for(int क्रमांक_अनुक्रमणिका=0;क्रमांक_अनुक्रमणिका<आकार;क्रमांक_अनुक्रमणिका++)डेटा[क्रमांक_अनुक्रमणिका]=जावाजाळे_मिळवा(क्रमांक_अनुक्रमणिका);return जाळे_लिहा(आयटम_संख्या,डेटा,आकार);
}
int32_t जावाप्रवाह_पॉर्ट(int32_t संचिका_हाताळा){int आयटम_संख्या=बाह्य_संख्या(संचिका_हाताळा);return आयटम_संख्या<0?जावापरतप्रवाह_पॉर्ट(संचिका_हाताळा):(int32_t)संचारजाळे_पोर्ट_नंबर(आयटम_संख्या);}
int32_t जावाप्रवाह_समकक्ष(int32_t संचिका_हाताळा){int आयटम_संख्या=बाह्य_संख्या(संचिका_हाताळा);return आयटम_संख्या<0?जावापरतप्रवाह_समकक्ष(संचिका_हाताळा):(int32_t)समकक्ष_पोर्ट_नंबर(आयटम_संख्या);}
int32_t जावाप्रवाह_पत्ता(int32_t संचिका_हाताळा){return बाह्य_संख्या(संचिका_हाताळा)<0?0x7f000001:दुहेरी_घटनाग्राहक[संचिका_हाताळा-32]?0:संचारजाळे_राज्य_वाचा(0,0);}
int32_t जावाप्रवाह_मिटवा(int32_t संचिका_हाताळा){int आयटम_संख्या=बाह्य_संख्या(संचिका_हाताळा);if(आयटम_संख्या>=0){संचारजाळे_मिटवा(आयटम_संख्या);बाह्य[संचिका_हाताळा-32]=0;}if(संचिका_हाताळा>=40&&संचिका_हाताळा<56)कोणतेही_पत्ता[संचिका_हाताळा-32]=दुहेरी_घटनाग्राहक[संचिका_हाताळा-32]=0;return जावापरतप्रवाह_मिटवा(संचिका_हाताळा);}
